begin;
create temp table chat_test_ids(label text primary key,id uuid not null);
insert into chat_test_ids select label,gen_random_uuid() from unnest(array['alice','bob','cara','outsider','inactive','nonparticipant']) label;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
select id,label||'-'||id||'@example.invalid',now(),jsonb_build_object('full_name',label,'company_name','Chat test '||label) from chat_test_ids;
update public.profiles set company_id=(select company_id from public.profiles where id=(select id from chat_test_ids where label='alice')),role=case when id=(select id from chat_test_ids where label='bob') then 'employee' when id=(select id from chat_test_ids where label='cara') then 'manager' else 'hr_admin' end where id in(select id from chat_test_ids where label not in('alice','outsider'));
update public.profiles set active=false where id=(select id from chat_test_ids where label='inactive');
grant select,insert on chat_test_ids to authenticated;
create temp table chat_test_results(test text,passed boolean);
grant select,insert on chat_test_results to authenticated;
create function pg_temp.chat_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is not true then raise exception 'TEST FAILED: %',label;end if;insert into chat_test_results values(label,true);end$$;
create function pg_temp.chat_denied(statement text,label text) returns void language plpgsql as $$declare denied boolean:=false;begin begin execute statement;exception when others then denied:=true;end;perform pg_temp.chat_assert(denied,label);end$$;
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='alice'),true);
set local role authenticated;
insert into chat_test_ids values('group',public.chat_create('group','Operations',(select array_agg(id) from chat_test_ids where label in('bob','cara'))));
insert into chat_test_ids values('direct',public.chat_create('direct','',(select array[id] from chat_test_ids where label='bob')));
select pg_temp.chat_assert(public.chat_create('direct','',(select array[id] from chat_test_ids where label='bob'))=(select id from chat_test_ids where label='direct'),'duplicate direct chats reuse conversation');
select pg_temp.chat_assert(jsonb_array_length(public.chat_people('',0))=3,'employee-safe roster exposes only active same-company teammates');
select pg_temp.chat_denied(format('select public.chat_create(''direct'','''',array[%L::uuid])',(select id from chat_test_ids where label='outsider')),'cannot create cross-company chat');
select pg_temp.chat_denied(format('select public.chat_create(''group'',''Invalid'',array[%L::uuid])',(select id from chat_test_ids where label='inactive')),'cannot invite inactive participant');
insert into chat_test_ids values('message',gen_random_uuid());
select public.chat_send((select id from chat_test_ids where label='group'),(select id from chat_test_ids where label='message'),'Hello team',null,(select array[id] from chat_test_ids where label='bob'),'/app/role-record?section=decision');
select public.chat_send((select id from chat_test_ids where label='group'),(select id from chat_test_ids where label='message'),'Hello team',null,(select array[id] from chat_test_ids where label='bob'),'/app/role-record?section=decision');
select pg_temp.chat_assert((select count(*) from public.chat_messages where id=(select id from chat_test_ids where label='message'))=1,'retry sends are idempotent');
select pg_temp.chat_denied(format('insert into public.chat_messages(id,conversation_id,company_id,sender_id,body) values(gen_random_uuid(),%L,%L,%L,''Bypass'')',(select id from chat_test_ids where label='group'),(select company_id from public.profiles where id=(select id from chat_test_ids where label='alice')),(select id from chat_test_ids where label='alice')),'direct table writes are blocked');
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='bob'),true);
select pg_temp.chat_assert((public.chat_inbox()->>'unread')::int=1 and (public.chat_inbox()->>'mentions')::int=1,'recipient sees one unread mention');
select pg_temp.chat_assert((select (x->>'unread')::int from jsonb_array_elements(public.chat_list(0)) x where x->>'id'=(select id::text from chat_test_ids where label='group'))=1,'conversation unread count is correct');
insert into chat_test_ids values('reply',gen_random_uuid());
select public.chat_send((select id from chat_test_ids where label='group'),(select id from chat_test_ids where label='reply'),'Thanks Alice',(select id from chat_test_ids where label='message'),'{}',null);
select pg_temp.chat_assert(jsonb_array_length(public.chat_detail((select id from chat_test_ids where label='group'),null,null)->'messages')=2,'participant can read original and reply');
select pg_temp.chat_assert(public.chat_detail((select id from chat_test_ids where label='group'),null,null)->'messages'->1->'reply'->>'body'='Hello team','reply includes original context');
select pg_temp.chat_assert(jsonb_array_length(public.chat_detail((select id from chat_test_ids where label='group'),null,(select id from chat_test_ids where label='message'))->'messages')=1,'notification anchor opens correct history');
select pg_temp.chat_denied(format('select public.chat_send(%L,gen_random_uuid(),''Leak'',%L,''{}'',null)',(select id from chat_test_ids where label='direct'),(select id from chat_test_ids where label='message')),'reply cannot reference another conversation');
select pg_temp.chat_denied(format('select public.chat_send(%L,gen_random_uuid(),''Tag'',null,array[%L::uuid],null)',(select id from chat_test_ids where label='group'),(select id from chat_test_ids where label='nonparticipant')),'mention cannot target nonparticipant');
select pg_temp.chat_denied(format('select public.chat_send(%L,gen_random_uuid(),''Link'',null,''{}'',''https://evil.invalid'')',(select id from chat_test_ids where label='group')),'external record links rejected');
select public.chat_read((select id from chat_test_ids where label='group'),(select seq from public.chat_messages where id=(select id from chat_test_ids where label='message')));
select public.chat_read((select id from chat_test_ids where label='group'),0);
select pg_temp.chat_assert((public.chat_inbox()->>'unread')::int=0,'read cursor is monotonic and clears delivered notification');
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='cara'),true);
select pg_temp.chat_assert((select count(*) from public.chat_messages)=2,'group participant cannot read unrelated direct conversation');
select pg_temp.chat_assert((public.chat_inbox()->>'unread')::int=2 and (public.chat_inbox()->>'mentions')::int=0,'ordinary group messages notify participants');
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='nonparticipant'),true);
select pg_temp.chat_assert((select count(*) from public.chat_messages)=0 and (select count(*) from public.chat_members)=0,'HR role does not grant private chat access');
select pg_temp.chat_denied(format('select public.chat_detail(%L,null,null)',(select id from chat_test_ids where label='group')),'HR nonparticipant cannot open chat RPC');
select pg_temp.chat_denied(format('select public.chat_send(%L,gen_random_uuid(),''Spoof'',null,''{}'',null)',(select id from chat_test_ids where label='group')),'nonparticipant cannot send');
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='outsider'),true);
select pg_temp.chat_assert((select count(*) from public.chat_conversations)=0 and (select count(*) from public.chat_notifications)=0,'cross-company table isolation');
select pg_temp.chat_denied(format('select public.chat_read(%L,999999)',(select id from chat_test_ids where label='group')),'cross-company read cursor denied');
reset role;
update public.profiles set active=false where id=(select id from chat_test_ids where label='bob');
select set_config('request.jwt.claim.sub',(select id::text from chat_test_ids where label='bob'),true);
set local role authenticated;
select pg_temp.chat_assert((select count(*) from public.chat_messages)=0,'deactivated participant immediately loses history');
select pg_temp.chat_denied('select public.chat_inbox()','deactivated participant loses notifications');
select pg_temp.chat_denied(format('select public.chat_send(%L,gen_random_uuid(),''Inactive'',null,''{}'',null)',(select id from chat_test_ids where label='group')),'deactivated participant cannot send');
reset role;
select set_config('request.jwt.claim.sub','',true);
set local role anon;
do $$begin begin perform public.chat_inbox();raise exception 'TEST FAILED anonymous RPC allowed';exception when insufficient_privilege then null;end;end$$;
reset role;
select * from chat_test_results;
rollback;
